package idempotency

import (
	"context"
	"sync"
)

// MemStore is an in-memory Store implementation, exported so every BFF's
// unit tests can exercise idempotency.Middleware without NATS. It
// reproduces NATSStore's Reserve semantics (first-writer-wins) under a
// mutex instead of jetstream.KeyValue's CAS, which is sufficient for
// single-process test concurrency (see TestMemStore_ConcurrentReserve).
type MemStore struct {
	mu      sync.Mutex
	entries map[string]Entry

	// FailNext, if set, is returned (and cleared) by the next call to any
	// method below, so tests can exercise the fail-open path deterministically.
	FailNext error
}

// NewMemStore returns an empty MemStore.
func NewMemStore() *MemStore {
	return &MemStore{entries: make(map[string]Entry)}
}

func (m *MemStore) takeFailure() error {
	if m.FailNext != nil {
		err := m.FailNext
		m.FailNext = nil
		return err
	}
	return nil
}

// Get implements Store.
func (m *MemStore) Get(_ context.Context, key string) (Entry, bool, error) {
	m.mu.Lock()
	defer m.mu.Unlock()
	if err := m.takeFailure(); err != nil {
		return Entry{}, false, err
	}
	e, ok := m.entries[key]
	return e, ok, nil
}

// Reserve implements Store using a mutex-guarded map instead of NATS CAS.
func (m *MemStore) Reserve(_ context.Context, key string, requestHash string) (bool, error) {
	m.mu.Lock()
	defer m.mu.Unlock()
	if err := m.takeFailure(); err != nil {
		return false, err
	}
	if _, exists := m.entries[key]; exists {
		return false, nil
	}
	m.entries[key] = Entry{RequestHash: requestHash, Pending: true}
	return true, nil
}

// Put implements Store.
func (m *MemStore) Put(_ context.Context, key string, entry Entry) error {
	m.mu.Lock()
	defer m.mu.Unlock()
	if err := m.takeFailure(); err != nil {
		return err
	}
	m.entries[key] = entry
	return nil
}

// Release implements Store.
func (m *MemStore) Release(_ context.Context, key string) error {
	m.mu.Lock()
	defer m.mu.Unlock()
	if err := m.takeFailure(); err != nil {
		return err
	}
	delete(m.entries, key)
	return nil
}

var _ Store = (*MemStore)(nil)


