package idempotency

import (
	"bytes"
	"crypto/sha256"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"strings"

	"github.com/google/uuid"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/auth"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/httpenvelope"
)

// HeaderName is the client-supplied idempotency key header, forwarded
// east-west via auth.HeaderIdempotencyKey.
const HeaderName = "Idempotency-Key"

// TenantIDFunc resolves the tenant/org ID to scope idempotency keys by. The
// default (DefaultTenantID) reads auth.ClaimsFromContext / the x-tenant-id
// header via auth.HeadersFromContext, in that order, falling back to the raw
// HTTP header for callers that haven't run auth.HTTPMiddleware (e.g. some
// integration test harnesses).
type TenantIDFunc func(r *http.Request) string

// DefaultTenantID is the TenantIDFunc used when Middleware is called via the
// two-argument form (no explicit resolver).
func DefaultTenantID(r *http.Request) string {
	if c, ok := auth.ClaimsFromContext(r.Context()); ok && c.OrgID != "" {
		return c.OrgID
	}
	if h := auth.HeadersFromContext(r.Context()); h.TenantID != "" {
		return h.TenantID
	}
	return r.Header.Get("X-Tenant-Id")
}

// Middleware returns an http.Handler middleware that enforces idempotency for
// state-mutating endpoints.
//
// The Idempotency-Key header is OPTIONAL. A request with no key (or an
// empty one) executes normally with no idempotency behavior at all — this
// is a deliberate relaxation from the original admin-bff-only version, which
// returned 400 when the header was absent. Repo-wide, most existing clients
// (including every Cypress spec that doesn't already send the header) don't
// send it, so requiring it would break them. A present key still must be a
// valid UUID, since it's used verbatim as a KV subject token component.
//
// Behaviour per request when a key IS present:
//
//  1. Key present but not a valid UUID        → 400 idempotency_key_invalid
//  2. Key not found in store (miss)           → Reserve the key (first-writer
//     wins); call next handler; if 2xx, store the result; otherwise release
//     the reservation so a retry isn't blocked for the rest of the TTL.
//  3. Reserve loses the race (Pending found)  → 409 idempotency_conflict
//     (concurrent duplicate) — the handler is NOT invoked a second time.
//  4. Key found, completed, hashes match      → replay cached response;
//     blank sensitive fields.
//  5. Key found, completed, hashes differ     → 422 idempotency_conflict
//     (same key reused for a different request body).
//
// Fail-open on storage errors (documented decision, defect #3 from the
// promotion): if the KV store is unreachable, Get/Reserve/Put/Release errors
// are swallowed and the handler runs uncached. Availability is prioritized
// over duplicate-suppression — a NATS outage must not take down every
// mutating route repo-wide just because idempotency bookkeeping can't
// happen. The tradeoff is that a client retry during a NATS outage can
// double-execute; TestMiddleware_FailsOpenOnStorageError proves the request
// still succeeds in that case, and pilot routes with real double-execution
// stakes (e.g. queue-bff :publish) still guard against that in their own
// handler logic where feasible.
//
// Sensitive-field blanking is unchanged from the promoted version: if the
// response handler sets X-Idempotency-Sensitive to a comma-separated list
// of JSON field names, the middleware stores those names in the KV entry
// and zeros them on every replay.
func Middleware(store Store) func(http.Handler) http.Handler {
	return MiddlewareWithTenant(store, DefaultTenantID)
}

// MiddlewareWithTenant is Middleware with an explicit TenantIDFunc, for
// callers (and tests) that want to control tenant resolution directly
// instead of relying on auth.ClaimsFromContext / auth.HeadersFromContext.
func MiddlewareWithTenant(store Store, tenantID TenantIDFunc) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			key := r.Header.Get(HeaderName)
			if key == "" {
				// No key supplied — idempotency is optional. Run normally.
				next.ServeHTTP(w, r)
				return
			}
			if !isValidUUID(key) {
				writeError(w, http.StatusBadRequest, "idempotency_key_invalid", "Idempotency-Key must be a valid UUID")
				return
			}

			// Tenant-scope the key (defect #1 fix): two different orgs
			// presenting the same client-generated key must never collide.
			scopedKey := ScopedKey(tenantID(r), key)

			// Buffer and restore body so downstream handlers can read it.
			body, err := io.ReadAll(r.Body)
			if err != nil {
				writeError(w, http.StatusBadRequest, "request_read_error", "failed to read request body")
				return
			}
			r.Body = io.NopCloser(bytes.NewReader(body))

			requestHash := hashBody(body)

			entry, found, err := store.Get(r.Context(), scopedKey)
			if err != nil {
				// Fail-open: storage unavailable, let the request through
				// uncached rather than blocking every mutating route on a
				// NATS outage. See the fail-open doc comment above.
				next.ServeHTTP(w, r)
				return
			}

			if found {
				if entry.Pending {
					// Another request holds the reservation right now.
					writeError(w, http.StatusConflict, "idempotency_conflict",
						"a request with this Idempotency-Key is already in progress")
					return
				}
				if entry.RequestHash != requestHash {
					writeError(w, http.StatusUnprocessableEntity, "idempotency_conflict",
						"Idempotency-Key already used with a different request body")
					return
				}
				// Cache hit — replay stored response.
				responseBody := entry.ResponseBody
				if len(entry.SensitiveFields) > 0 {
					responseBody = blankFields(responseBody, entry.SensitiveFields)
				}
				w.Header().Set("Content-Type", "application/json")
				w.WriteHeader(entry.StatusCode)
				_, _ = w.Write(responseBody)
				return
			}

			// Cache miss — reserve the key (first-writer-wins) before
			// running the handler (defect #2 fix: no in-flight lock).
			reserved, err := store.Reserve(r.Context(), scopedKey, requestHash)
			if err != nil {
				// Fail-open, same rationale as the Get error branch above.
				next.ServeHTTP(w, r)
				return
			}
			if !reserved {
				// Lost the race to a concurrent identical request between
				// our Get and our Reserve. Do not run the handler again.
				writeError(w, http.StatusConflict, "idempotency_conflict",
					"a request with this Idempotency-Key is already in progress")
				return
			}

			rec := newResponseRecorder(w)
			next.ServeHTTP(rec, r)

			if rec.status >= 200 && rec.status < 300 {
				sensitiveFields := parseSensitiveFields(rec.Header().Get("X-Idempotency-Sensitive"))
				storedBody := rec.body.Bytes()
				if len(sensitiveFields) > 0 {
					storedBody = blankFields(storedBody, sensitiveFields)
				}
				newEntry := Entry{
					RequestHash:     requestHash,
					ResponseBody:    storedBody,
					StatusCode:      rec.status,
					SensitiveFields: sensitiveFields,
				}
				// Best-effort store: ignore errors so the handler response
				// is not impacted by a transient NATS failure (fail-open).
				_ = store.Put(r.Context(), scopedKey, newEntry)
			} else {
				// Release the reservation so a retry of a failed request
				// isn't blocked for the rest of the TTL window.
				_ = store.Release(r.Context(), scopedKey)
			}
		})
	}
}

// responseRecorder wraps an http.ResponseWriter to capture status + body.
//
// Defense-in-depth (CWE-079 / CodeQL go/reflected-xss): this recorder
// tees an inner handler's response, which static analysis flags as a
// reflected-XSS sink because the middleware can't statically prove the
// handler sanitized its output. Before forwarding the first WriteHeader
// or Write, the recorder defensively sets `X-Content-Type-Options:
// nosniff` and a `Content-Type: application/json` default when the
// handler omitted one.
type responseRecorder struct {
	http.ResponseWriter
	status      int
	body        bytes.Buffer
	wroteHeader bool
}

func newResponseRecorder(w http.ResponseWriter) *responseRecorder {
	return &responseRecorder{ResponseWriter: w, status: http.StatusOK}
}

// WriteHeader applies defensive response headers, captures the status
// code, and forwards once to the underlying writer. Idempotent —
// subsequent calls are no-ops (matching http.ResponseWriter semantics).
func (r *responseRecorder) WriteHeader(code int) {
	if r.wroteHeader {
		return
	}
	h := r.Header()
	if h.Get("Content-Type") == "" {
		h.Set("Content-Type", "application/json")
	}
	if h.Get("X-Content-Type-Options") == "" {
		h.Set("X-Content-Type-Options", "nosniff")
	}
	r.status = code
	r.wroteHeader = true
	r.ResponseWriter.WriteHeader(code)
}

// Write tees the body into the internal buffer and forwards to the
// underlying writer. If WriteHeader has not been called yet, it is
// invoked with 200 first so the defensive headers above always run
// before any byte reaches the network.
func (r *responseRecorder) Write(b []byte) (int, error) {
	if !r.wroteHeader {
		r.WriteHeader(http.StatusOK)
	}
	r.body.Write(b)
	return r.ResponseWriter.Write(b)
}

// hashBody computes the SHA-256 hex digest of b.
func hashBody(b []byte) string {
	sum := sha256.Sum256(b)
	return fmt.Sprintf("%x", sum)
}

// isValidUUID returns true if s parses as a valid UUID.
func isValidUUID(s string) bool {
	_, err := uuid.Parse(s)
	return err == nil
}

// parseSensitiveFields splits a comma-separated header value into field names,
// trimming whitespace and dropping empty entries.
func parseSensitiveFields(header string) []string {
	if header == "" {
		return nil
	}
	parts := strings.Split(header, ",")
	out := make([]string, 0, len(parts))
	for _, p := range parts {
		if f := strings.TrimSpace(p); f != "" {
			out = append(out, f)
		}
	}
	return out
}

// blankFields decodes JSON in body, walks it recursively — into nested
// objects and array elements at any depth — and sets each key whose name
// matches one of fields to an empty string, then re-encodes. If decoding
// fails the original body is returned unchanged so the caller always gets a
// valid response.
func blankFields(body []byte, fields []string) []byte {
	var v any
	if err := json.Unmarshal(body, &v); err != nil {
		return body
	}
	fieldSet := make(map[string]struct{}, len(fields))
	for _, f := range fields {
		fieldSet[f] = struct{}{}
	}
	out, err := json.Marshal(blankValue(v, fieldSet))
	if err != nil {
		return body
	}
	return out
}

// blankValue recursively walks v, blanking any object key present in fields.
// Objects and array elements are visited depth-first; scalars pass through
// unchanged.
func blankValue(v any, fields map[string]struct{}) any {
	switch val := v.(type) {
	case map[string]any:
		for k, sub := range val {
			if _, sensitive := fields[k]; sensitive {
				val[k] = ""
				continue
			}
			val[k] = blankValue(sub, fields)
		}
		return val
	case []any:
		for i, elem := range val {
			val[i] = blankValue(elem, fields)
		}
		return val
	default:
		return val
	}
}

// writeError writes the platform's standard JSON error envelope. This used
// to be a 14th package-private copy of the writeJSON/writeError pattern
// duplicated across the BFFs' handlers packages (missing even the "data"
// key that every other copy had); it now shims the shared
// platform/libs/go/httpenvelope package like the rest, which adds the
// "data": null member the other copies always had. The "error" object's
// shape is unchanged, so no client reading .error is affected.
func writeError(w http.ResponseWriter, status int, code, msg string) {
	httpenvelope.WriteError(w, status, code, msg)
}


