package idempotency_test

import (
	"context"
	"errors"
	"net/http"
	"net/http/httptest"
	"strings"
	"sync"
	"sync/atomic"
	"testing"
	"time"

	"github.com/stretchr/testify/require"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/auth"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/idempotency"
)

const testKey = "9c858e4e-1e3d-4f0a-9d0e-000000000001"

func tenantMiddleware(store idempotency.Store, tenant string) func(http.Handler) http.Handler {
	return idempotency.MiddlewareWithTenant(store, func(*http.Request) string { return tenant })
}

func countingHandler(calls *int32, status int, body string) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		atomic.AddInt32(calls, 1)
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(status)
		_, _ = w.Write([]byte(body))
	})
}

func doRequest(h http.Handler, key, body string) *httptest.ResponseRecorder {
	req := httptest.NewRequest(http.MethodPost, "/thing", strings.NewReader(body))
	if key != "" {
		req.Header.Set(idempotency.HeaderName, key)
	}
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, req)
	return rec
}

// --- Acceptance 1 (relaxed): optional key ----------------------------------

func TestMiddleware_NoKey_RunsNormally_NoStoreInteraction(t *testing.T) {
	store := idempotency.NewMemStore()
	var calls int32
	h := tenantMiddleware(store, "org-1")(countingHandler(&calls, 200, `{"ok":true}`))

	rec := doRequest(h, "", `{"a":1}`)
	require.Equal(t, http.StatusOK, rec.Code)
	require.EqualValues(t, 1, calls)

	rec2 := doRequest(h, "", `{"a":1}`)
	require.Equal(t, http.StatusOK, rec2.Code)
	require.EqualValues(t, 2, calls, "no key means no dedup — handler runs every time")
}

func TestMiddleware_InvalidKey_400(t *testing.T) {
	store := idempotency.NewMemStore()
	var calls int32
	h := tenantMiddleware(store, "org-1")(countingHandler(&calls, 200, `{}`))

	rec := doRequest(h, "not-a-uuid", `{}`)
	require.Equal(t, http.StatusBadRequest, rec.Code)
	require.EqualValues(t, 0, calls)
}

// --- Acceptance 4/5-ish: basic replay + conflict ---------------------------

func TestMiddleware_Replay_SameHash_NoSecondExecution(t *testing.T) {
	store := idempotency.NewMemStore()
	var calls int32
	h := tenantMiddleware(store, "org-1")(countingHandler(&calls, 201, `{"data":{"id":"u1"}}`))

	first := doRequest(h, testKey, `{"a":1}`)
	require.Equal(t, http.StatusCreated, first.Code)

	second := doRequest(h, testKey, `{"a":1}`)
	require.Equal(t, http.StatusCreated, second.Code)
	require.JSONEq(t, `{"data":{"id":"u1"}}`, second.Body.String())
	require.EqualValues(t, 1, calls, "replay must not re-run the handler")
}

func TestMiddleware_DifferentBody_SameKey_422Conflict(t *testing.T) {
	store := idempotency.NewMemStore()
	var calls int32
	h := tenantMiddleware(store, "org-1")(countingHandler(&calls, 200, `{}`))

	first := doRequest(h, testKey, `{"a":1}`)
	require.Equal(t, http.StatusOK, first.Code)

	second := doRequest(h, testKey, `{"a":2}`)
	require.Equal(t, http.StatusUnprocessableEntity, second.Code)
	require.EqualValues(t, 1, calls)
}

func TestMiddleware_SensitiveFields_BlankedOnReplay(t *testing.T) {
	store := idempotency.NewMemStore()
	handler := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("X-Idempotency-Sensitive", "temp_password")
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write([]byte(`{"data":{"user_id":"u1","temp_password":"s3cr3t"}}`))
	})
	h := tenantMiddleware(store, "org-1")(handler)

	first := doRequest(h, testKey, `{}`)
	require.Contains(t, first.Body.String(), "s3cr3t", "first caller still gets the live value")

	second := doRequest(h, testKey, `{}`)
	require.NotContains(t, second.Body.String(), "s3cr3t")
	require.Contains(t, second.Body.String(), `"temp_password":""`)
}

func TestMiddleware_NonSuccess_NotCached_ReleasesLock(t *testing.T) {
	store := idempotency.NewMemStore()
	var calls int32
	h := tenantMiddleware(store, "org-1")(countingHandler(&calls, 500, `{"error":"boom"}`))

	first := doRequest(h, testKey, `{}`)
	require.Equal(t, http.StatusInternalServerError, first.Code)
	require.EqualValues(t, 1, calls)

	// Retry after a failed attempt must run the handler again, not 409.
	second := doRequest(h, testKey, `{}`)
	require.Equal(t, http.StatusInternalServerError, second.Code)
	require.EqualValues(t, 2, calls)
}

// --- Acceptance 2: cross-tenant isolation ----------------------------------

func TestMiddleware_SameKey_DifferentOrgs_DoNotCollide(t *testing.T) {
	store := idempotency.NewMemStore()
	var callsA, callsB int32
	hA := tenantMiddleware(store, "org-A")(countingHandler(&callsA, 200, `{"org":"A"}`))
	hB := tenantMiddleware(store, "org-B")(countingHandler(&callsB, 200, `{"org":"B"}`))

	recA := doRequest(hA, testKey, `{"same":"body"}`)
	recB := doRequest(hB, testKey, `{"same":"body"}`)

	require.Equal(t, http.StatusOK, recA.Code)
	require.Equal(t, http.StatusOK, recB.Code)
	require.JSONEq(t, `{"org":"A"}`, recA.Body.String())
	require.JSONEq(t, `{"org":"B"}`, recB.Body.String())
	require.EqualValues(t, 1, callsA)
	require.EqualValues(t, 1, callsB, "org B must execute its own handler, not replay org A's cached response")
}

// --- Acceptance 3: concurrent same-key requests → one execution + one 409 -

func TestMiddleware_ConcurrentSameKey_OneExecutionOneConflict(t *testing.T) {
	store := idempotency.NewMemStore()
	var calls int32
	release := make(chan struct{})
	handler := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		atomic.AddInt32(&calls, 1)
		<-release // hold the handler open so the second request races in
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write([]byte(`{"ok":true}`))
	})
	h := tenantMiddleware(store, "org-1")(handler)

	var wg sync.WaitGroup
	codes := make([]int, 2)
	wg.Add(2)
	for i := 0; i < 2; i++ {
		go func(i int) {
			defer wg.Done()
			rec := doRequest(h, testKey, `{"a":1}`)
			codes[i] = rec.Code
		}(i)
	}

	// Give both goroutines a chance to reach the Reserve race before
	// letting the winner's handler finish.
	require.Eventually(t, func() bool { return atomic.LoadInt32(&calls) >= 1 }, time.Second, time.Millisecond)
	close(release)
	wg.Wait()

	require.EqualValues(t, 1, calls, "only the first-writer-wins reservation runs the handler")
	sawOK, sawConflict := 0, 0
	for _, c := range codes {
		switch c {
		case http.StatusOK:
			sawOK++
		case http.StatusConflict:
			sawConflict++
		}
	}
	require.Equal(t, 1, sawOK)
	require.Equal(t, 1, sawConflict)
}

// --- Defect #3: fail-open on storage error, documented and tested ---------

func TestMiddleware_FailsOpenOnStorageError(t *testing.T) {
	store := idempotency.NewMemStore()
	store.FailNext = errors.New("nats unavailable")
	var calls int32
	h := tenantMiddleware(store, "org-1")(countingHandler(&calls, 200, `{"ok":true}`))

	rec := doRequest(h, testKey, `{}`)
	require.Equal(t, http.StatusOK, rec.Code, "a storage error on Get must not block the request")
	require.EqualValues(t, 1, calls)
}

func TestMiddleware_FailsOpenOnReserveError(t *testing.T) {
	store := idempotency.NewMemStore()
	var calls int32
	h := tenantMiddleware(store, "org-1")(countingHandler(&calls, 200, `{"ok":true}`))

	// Prime a Get miss (no failure yet), then fail the subsequent Reserve.
	_, found, err := store.Get(context.Background(), idempotency.ScopedKey("org-1", testKey))
	require.NoError(t, err)
	require.False(t, found)
	store.FailNext = errors.New("nats unavailable")

	rec := doRequest(h, testKey, `{}`)
	require.Equal(t, http.StatusOK, rec.Code, "a storage error on Reserve must not block the request")
	require.EqualValues(t, 1, calls)
}

// --- Middleware (default tenant resolver) ----------------------------------

func TestMiddleware_DefaultTenantID_FromClaims(t *testing.T) {
	store := idempotency.NewMemStore()
	var calls int32
	h := idempotency.Middleware(store)(countingHandler(&calls, 200, `{"ok":true}`))

	req := httptest.NewRequest(http.MethodPost, "/thing", strings.NewReader(`{"a":1}`))
	req.Header.Set(idempotency.HeaderName, testKey)
	req = req.WithContext(auth.ClaimsIntoContext(req.Context(), auth.Claims{OrgID: "org-claims"}))
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, req)
	require.Equal(t, http.StatusOK, rec.Code)
	require.EqualValues(t, 1, calls)

	// Replay with the same claims-derived tenant hits the cache.
	req2 := httptest.NewRequest(http.MethodPost, "/thing", strings.NewReader(`{"a":1}`))
	req2.Header.Set(idempotency.HeaderName, testKey)
