const testKey = "9c858e4e-1e3d-4f0a-9d0e-000000000001"

func tenantMiddleware(store idempotency.Store, tenant string) func(http.Handler) http.Handler {
	return idempotency.MiddlewareWithTenant(store, func(*http.Request) string { return tenant })
}

func countingHandler(calls *int32, status int, body string) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		atomic.AddInt32(calls, 1)
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(status)
		_, _ = w.Write([]byte(body))
	})
}

func doRequest(h http.Handler, key, body string) *httptest.ResponseRecorder {
	req := httptest.NewRequest(http.MethodPost, "/thing", strings.NewReader(body))
	if key != "" {
		req.Header.Set(idempotency.HeaderName, key)
	}
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, req)
	return rec
}

