	h := tenantMiddleware(store, "org-1")(countingHandler(&calls, 200, `{"ok":true}`))

	rec := doRequest(h, "", `{"a":1}`)
	require.Equal(t, http.StatusOK, rec.Code)
	require.EqualValues(t, 1, calls)

	rec2 := doRequest(h, "", `{"a":1}`)
	require.Equal(t, http.StatusOK, rec2.Code)
	require.EqualValues(t, 2, calls, "no key means no dedup — handler runs every time")
