	require.JSONEq(t, `{"org":"B"}`, recB.Body.String())
	require.EqualValues(t, 1, callsA)
	require.EqualValues(t, 1, callsB, "org B must execute its own handler, not replay org A's cached response")
}

// --- Acceptance 3: concurrent same-key requests → one execution + one 409 -

func TestMiddleware_ConcurrentSameKey_OneExecutionOneConflict(t *testing.T) {
	store := idempotency.NewMemStore()
	var calls int32
	release := make(chan struct{})
	handler := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		atomic.AddInt32(&calls, 1)
		<-release // hold the handler open so the second request races in
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write([]byte(`{"ok":true}`))
	})
	h := tenantMiddleware(store, "org-1")(handler)

	var wg sync.WaitGroup
	codes := make([]int, 2)
	wg.Add(2)
	for i := 0; i < 2; i++ {
		go func(i int) {
			defer wg.Done()
			rec := doRequest(h, testKey, `{"a":1}`)
			codes[i] = rec.Code
		}(i)
	}

	// Give both goroutines a chance to reach the Reserve race before
	// letting the winner's handler finish.
	require.Eventually(t, func() bool { return atomic.LoadInt32(&calls) >= 1 }, time.Second, time.Millisecond)
	close(release)
	wg.Wait()

	require.EqualValues(t, 1, calls, "only the first-writer-wins reservation runs the handler")
	sawOK, sawConflict := 0, 0
	for _, c := range codes {
		switch c {
		case http.StatusOK:
			sawOK++
		case http.StatusConflict:
			sawConflict++
		}
	}
	require.Equal(t, 1, sawOK)
	require.Equal(t, 1, sawConflict)
}

