// Package idempotency provides NATS JetStream KV-backed idempotency for
// mutating HTTP endpoints across every BFF. It caches
// {request_hash, response_body, status_code} per (tenant, Idempotency-Key)
// pair with a configurable TTL (default 24h). On replay the stored response
// is returned verbatim except that sensitive JSON fields listed in the
// entry's SensitiveFields slice are zeroed out before sending to the caller.
//
// This package was promoted from services/admin-bff/internal/idempotency
// (Task 6.1) so every BFF can share one implementation instead of each
// growing its own copy. Two defects present in the admin-bff-only version
// were fixed during the promotion:
//
//  1. Keys were not tenant-scoped: two different orgs replaying the same
//     client-generated Idempotency-Key collided in the shared KV bucket,
//     which is a cross-org replay/leak risk. ScopedKey below namespaces
//     every key by tenant ID before it ever reaches the store.
//  2. There was no in-flight lock: two concurrent requests carrying the
//     same key both executed the handler, because the store used a plain
//     kv.Put. Reserve (below) uses kv.Create for first-writer-wins, mirroring
//     services/agents-svc/internal/hitl/store.go's NATSIdempotencyStore.
//
// Design choice retained from the promoted version: sensitive fields (e.g.,
// temp_password, an API key's plaintext secret) are blanked BEFORE storage,
// not just on replay. The KV bucket must never hold a live secret for the
// full TTL window. The handler opts in by setting the
// X-Idempotency-Sensitive header to a comma-separated list of field names
// before calling the next handler.
package idempotency

import (
	"context"
	"encoding/json"
	"errors"
	"strings"
	"time"

	"github.com/nats-io/nats.go/jetstream"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/observability"
)

// BucketName is the NATS KV bucket used for idempotency storage.
const BucketName = "bff-idempotency"

// DefaultTTL is the default TTL for idempotency entries.
const DefaultTTL = 24 * time.Hour

// Entry is the value stored per scoped key in the KV bucket.
type Entry struct {
	// RequestHash is the SHA-256 hex digest of the original request body.
	RequestHash string `json:"request_hash"`
	// ResponseBody is the raw JSON response body captured from the handler.
	ResponseBody []byte `json:"response_body,omitempty"`
	// StatusCode is the HTTP status code returned by the handler.
	StatusCode int `json:"status_code,omitempty"`
	// SensitiveFields lists JSON field names to blank on replay. The handler
	// populates this by setting X-Idempotency-Sensitive on the response.
	SensitiveFields []string `json:"sensitive_fields,omitempty"`
	// Pending is true for the placeholder written by Reserve, before the
	// handler has finished. A Get that observes Pending==true means another
	// request is currently executing the handler for this key — the caller
	// (the middleware) must not treat this as a normal cache hit.
	Pending bool `json:"pending,omitempty"`
}

// Store is the abstraction over the KV bucket.
//
// Production implementation: *NATSStore backed by NATS JetStream KV.
// Test implementation: *MemStore — an in-memory fake that avoids NATS.
type Store interface {
	// Get retrieves an entry by scoped key.
	// Returns (entry, true, nil) on hit (pending or completed),
	// (zero, false, nil) on miss, and (zero, false, err) on storage error.
	Get(ctx context.Context, key string) (Entry, bool, error)
	// Reserve atomically creates a Pending placeholder for key if, and only
	// if, no entry currently exists for it (first-writer-wins, via
	// kv.Create). Returns (true, nil) when the caller won the reservation
	// and must now run the handler. Returns (false, nil) when an entry
	// already exists (either pending — a concurrent duplicate — or
	// completed — a replay); the caller should Get to disambiguate.
	// Returns (false, err) on storage error.
	Reserve(ctx context.Context, key string, requestHash string) (bool, error)
	// Put stores the final entry for key, overwriting the Pending
	// placeholder (or any prior value).
	Put(ctx context.Context, key string, entry Entry) error
	// Release deletes the entry for key. Used to release a Reserve lock
	// after the handler returned a non-2xx response, so a retry of a
	// failed request is not blocked for the rest of the TTL window.
	Release(ctx context.Context, key string) error
}

// ScopedKey namespaces a raw client-supplied Idempotency-Key by tenant so
// that two different orgs can never collide on the same key value in the
// shared KV bucket (defect #1 fixed during the platform/libs/go promotion).
// "." is used as a separator, and any literal "." or ":" in either
// component is replaced with "_" first — NATS KV keys are subject-like
// tokens, and ":" in particular is rejected outright by jetstream.KeyValue
// (see services/agents-svc/internal/hitl/store.go's sanitizeKey).
func ScopedKey(tenantID, key string) string {
	return sanitizeKeyPart(tenantID) + "." + sanitizeKeyPart(key)
}

func sanitizeKeyPart(s string) string {
	s = strings.ReplaceAll(s, ":", "_")
	s = strings.ReplaceAll(s, ".", "_")
	return s
}

// NATSStore is the production Store backed by NATS JetStream KV.
type NATSStore struct {
	kv jetstream.KeyValue
}

// NewNATSStore creates (or opens) the NATS KV bucket and returns a NATSStore.
//
// The bucket is created lazily so that a BFF can start without NATS being
// available at boot if the first request is served before NATS is ready.
func NewNATSStore(ctx context.Context, js jetstream.JetStream, ttl time.Duration) (*NATSStore, error) {
	if ttl <= 0 {
		ttl = DefaultTTL
	}
	kv, err := js.CreateOrUpdateKeyValue(ctx, jetstream.KeyValueConfig{
		Bucket: BucketName,
		TTL:    ttl,
	})
	if err != nil {
		return nil, observability.Wrap(observability.CodeServiceUnavailable, "create idempotency kv bucket", err)
	}
	return &NATSStore{kv: kv}, nil
}

// Get retrieves an idempotency entry from the NATS KV bucket.
func (s *NATSStore) Get(ctx context.Context, key string) (Entry, bool, error) {
	kve, err := s.kv.Get(ctx, key)
	if err != nil {
		if isNotFound(err) {
			return Entry{}, false, nil
		}
		return Entry{}, false, observability.Wrap(observability.CodeServiceUnavailable, "idempotency kv get", err)
	}
	var e Entry
	if err := json.Unmarshal(kve.Value(), &e); err != nil {
		return Entry{}, false, observability.Wrap(observability.CodeInternal, "idempotency entry unmarshal", err)
	}
	return e, true, nil
}

// Reserve creates a Pending placeholder for key using kv.Create, which NATS
// JetStream KV only succeeds when the key does not currently exist. This is
// the first-writer-wins lock that fixes defect #2 (concurrent same-key
// requests both executing the handler): only one of any set of racing
// Reserve calls for the same key gets (true, nil); every other one gets
// (false, nil) and must not run the handler.
func (s *NATSStore) Reserve(ctx context.Context, key string, requestHash string) (bool, error) {
	body, err := json.Marshal(Entry{RequestHash: requestHash, Pending: true})
	if err != nil {
		return false, observability.Wrap(observability.CodeInternal, "idempotency placeholder marshal", err)
	}
	if _, err := s.kv.Create(ctx, key, body); err != nil {
		if errors.Is(err, jetstream.ErrKeyExists) {
			return false, nil
		}
		return false, observability.Wrap(observability.CodeServiceUnavailable, "idempotency kv create", err)
	}
	return true, nil
}

// Put stores an idempotency entry in the NATS KV bucket, overwriting the
// Pending placeholder written by Reserve (or any prior value).
func (s *NATSStore) Put(ctx context.Context, key string, entry Entry) error {
	body, err := json.Marshal(entry)
	if err != nil {
		return observability.Wrap(observability.CodeInternal, "idempotency entry marshal", err)
	}
	if _, err := s.kv.Put(ctx, key, body); err != nil {
		return observability.Wrap(observability.CodeServiceUnavailable, "idempotency kv put", err)
	}
	return nil
}

// Release deletes the entry for key, releasing a Reserve lock that will
// never be completed by Put (the handler returned a non-2xx response). This
// keeps a single failed attempt from blocking every retry of the same key
// for the rest of the TTL window.
func (s *NATSStore) Release(ctx context.Context, key string) error {
	if err := s.kv.Delete(ctx, key); err != nil && !isNotFound(err) {
		return observability.Wrap(observability.CodeServiceUnavailable, "idempotency kv delete", err)
	}
	return nil
}

// isNotFound returns true when the NATS error indicates a missing key.
// NATS JetStream returns jetstream.ErrKeyNotFound for missing keys.
func isNotFound(err error) bool {
	return err != nil && err.Error() == jetstream.ErrKeyNotFound.Error()
}


