func TestMemStore_MissOnEmpty(t *testing.T) {
	s := idempotency.NewMemStore()
	_, found, err := s.Get(context.Background(), "some-key")
	require.NoError(t, err)
	require.False(t, found)
}

func TestMemStore_ReserveThenPutThenGet(t *testing.T) {
	s := idempotency.NewMemStore()
	ok, err := s.Reserve(context.Background(), "key-1", "hash-1")
	require.NoError(t, err)
	require.True(t, ok)

	entry := idempotency.Entry{
		RequestHash:  "hash-1",
		ResponseBody: []byte(`{"data":{"user_id":"u1"}}`),
		StatusCode:   200,
	}
	require.NoError(t, s.Put(context.Background(), "key-1", entry))

	got, found, err := s.Get(context.Background(), "key-1")
	require.NoError(t, err)
	require.True(t, found)
	require.Equal(t, entry.RequestHash, got.RequestHash)
	require.Equal(t, entry.ResponseBody, got.ResponseBody)
	require.Equal(t, entry.StatusCode, got.StatusCode)
	require.False(t, got.Pending)
}

func TestMemStore_Reserve_SecondCallLoses(t *testing.T) {
	s := idempotency.NewMemStore()
	ok1, err := s.Reserve(context.Background(), "key-1", "hash-1")
	require.NoError(t, err)
	require.True(t, ok1)

	ok2, err := s.Reserve(context.Background(), "key-1", "hash-1")
	require.NoError(t, err)
	require.False(t, ok2, "a second Reserve for the same key must lose the race")

	got, found, err := s.Get(context.Background(), "key-1")
	require.NoError(t, err)
	require.True(t, found)
	require.True(t, got.Pending)
}

func TestMemStore_Release_AllowsReReserve(t *testing.T) {
	s := idempotency.NewMemStore()
	ok, err := s.Reserve(context.Background(), "key-1", "hash-1")
	require.NoError(t, err)
	require.True(t, ok)

	require.NoError(t, s.Release(context.Background(), "key-1"))

	_, found, err := s.Get(context.Background(), "key-1")
	require.NoError(t, err)
	require.False(t, found)

	ok2, err := s.Reserve(context.Background(), "key-1", "hash-2")
	require.NoError(t, err)
	require.True(t, ok2, "after Release, the key must be reservable again")
}

func TestMemStore_SensitiveFieldsRoundTrip(t *testing.T) {
	s := idempotency.NewMemStore()
	entry := idempotency.Entry{
		RequestHash:     "abc",
		ResponseBody:    []byte(`{"user_id":"u1","temp_password":"s3cr3t"}`),
		StatusCode:      200,
		SensitiveFields: []string{"temp_password"},
	}
	require.NoError(t, s.Put(context.Background(), "k", entry))

	got, found, err := s.Get(context.Background(), "k")
	require.NoError(t, err)
	require.True(t, found)
	require.Equal(t, []string{"temp_password"}, got.SensitiveFields)
}

